6		"sync/atomic"
7		"testing"
8	
9		"github.com/zalando/go-keyring"
10	)
11	
12	// hostStoreUnderTestMessage is the panic text of refuseUnderTest. It names what
13	// to do, because the person reading it is a developer whose test just reached
14	// the real secret store of the machine (DEVDESK-610).
15	const hostStoreUnderTestMessage = "credentials: a test reached the host secret store (%s) " +
16		"without isolation; call fakekeyring.Install() in TestMain or fakekeyring.Fresh(t) " +
17		"(DEVDESK-610, docs/architecture/configuration.md)"
18	
19	// HostStore is the host secret manager as KeyringStorage and KeyringAvailable
20	// see it. The contract on a missing entry:
21	//   - Get returns an error for which errors.Is(err, ErrNotFound). go-keyring's
22	//     own ErrNotFound is not recognized here; goKeyring maps it.
23	//   - Delete returns nil.
24	//
25	// An implementation that returns any other error for a missing entry is seen as
26	// a real failure of the store: KeyringAvailable reports it unreachable.
27	type HostStore interface {
28		Get(service, account string) (string, error)
29		Set(service, account, secret string) error
30		Delete(service, account string) error
31	}
32	
33	// hostBox lets an atomic.Pointer hold an interface value, so a Cmd reading the
34	// current store while a t.Cleanup restores the previous one is not a data race.
35	type hostBox struct{ store HostStore }
36	
37	var currentStore atomic.Pointer[hostBox]
38	
39	// hostReachableUnderTest is set only by the TestMain of this package, whose
40	// tests mock go-keyring themselves and run git against a hermetic config. In
41	// any other test binary it stays false, so the real store is refused.
42	var hostReachableUnderTest atomic.Bool
43	
44	// currentHost returns the store in use: goKeyring{} unless a test swapped it.
45	func currentHost() HostStore {
46		if b := currentStore.Load(); b != nil {
47			return b.store
48		}
49		return goKeyring{}
50	}
51	
52	// SwapHostStoreForTest installs s and returns the store it replaces. It panics
53	// outside a test binary and when s is nil. Only _test.go files and
54	// internal/testutil/fakekeyring may call it.
55	func SwapHostStoreForTest(s HostStore) HostStore {
56		if !testing.Testing() {
57			panic("credentials: SwapHostStoreForTest called outside a test binary")
58		}
59		if s == nil {
60			panic("credentials: SwapHostStoreForTest called with a nil HostStore; pass the store to restore, as returned by the previous call")
61		}
62		if prev := currentStore.Swap(&hostBox{store: s}); prev != nil {
63			return prev.store
64		}
65		return goKeyring{}
66	}
67	
68	// refuseUnderTest panics with hostStoreUnderTestMessage when the code runs in a
69	// test binary that has not allowed the real host store. It panics rather than
70	// returning an error: an error would make Select fall back to memory and the
71	// test would pass, leaving the guard silent. op names the operation reached.
72	func refuseUnderTest(op string) {
73		if testing.Testing() && !hostReachableUnderTest.Load() {
74			panic(fmt.Sprintf(hostStoreUnderTestMessage, op))
75		}
76	}
77	
78	// goKeyring is the production HostStore and the only place go-keyring is
79	// called. Every method runs the test guard first.
80	type goKeyring struct{}
81	
82	func (goKeyring) Get(service, account string) (string, error) {
83		refuseUnderTest("keyring get")
84		secret, err := keyring.Get(service, account)
85		if errors.Is(err, keyring.ErrNotFound) {
86			return "", fmt.Errorf("%w: %v", ErrNotFound, err)
87		}
88		return secret, err
89	}
90	
91	func (goKeyring) Set(service, account, secret string) error {
92		refuseUnderTest("keyring set")
93		return keyring.Set(service, account, secret)
94	}
95	
96	func (goKeyring) Delete(service, account string) error {
97		refuseUnderTest("keyring delete")
98		err := keyring.Delete(service, account)
99		if errors.Is(err, keyring.ErrNotFound) {
100			return nil
101		}
102		return err
103	}
